<?php
session_start();
if (empty($_SESSION['auth_user'])) { header('Location: /casa/login.php'); exit; }
require_once __DIR__ . '/api/db.php';
$pdo = get_db_pdo();

if (empty($_SESSION['csrf_automation'])) $_SESSION['csrf_automation'] = bin2hex(random_bytes(24));
$csrf = $_SESSION['csrf_automation'];
$message=''; $error='';

function h($v){ return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); }
function slugify_auto($s){ $s=strtolower(trim((string)$s)); $a=iconv('UTF-8','ASCII//TRANSLIT',$s); if($a!==false)$s=$a; $s=preg_replace('/[^a-z0-9\-]+/','-',$s); return trim($s,'-'); }
function json_arr($text){ $v=json_decode((string)$text,true); if(!is_array($v)) throw new RuntimeException('JSON inválido.'); return $v; }

if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!hash_equals($csrf,$_POST['csrf']??'')) $error='Sessão inválida. Atualize a página.';
    else try {
        $action=$_POST['action']??'';
        if ($action==='scene_save') {
            $id=(int)($_POST['id']??0); $name=trim($_POST['name']??''); if($name==='')throw new RuntimeException('Informe o nome da cena.');
            $slug=slugify_auto($_POST['slug']??$name); $desc=trim($_POST['description']??''); $risk=max(0,min(4,(int)($_POST['risk_level']??1))); $active=isset($_POST['active'])?1:0; $stop=isset($_POST['stop_on_error'])?1:0;
            if($id>0){$pdo->prepare('UPDATE scenes SET slug=:s,nome=:n,descricao=:d,ativo=:a,stop_on_error=:e,risk_level=:r WHERE id=:id')->execute([':s'=>$slug,':n'=>$name,':d'=>$desc,':a'=>$active,':e'=>$stop,':r'=>$risk,':id'=>$id]);}
            else{$pdo->prepare('INSERT INTO scenes(slug,nome,descricao,ativo,stop_on_error,risk_level) VALUES(:s,:n,:d,:a,:e,:r)')->execute([':s'=>$slug,':n'=>$name,':d'=>$desc,':a'=>$active,':e'=>$stop,':r'=>$risk]);$id=(int)$pdo->lastInsertId();}
            $actions=json_arr($_POST['actions_json']??'[]');
            $pdo->beginTransaction();
            $pdo->prepare('DELETE FROM scene_actions WHERE scene_id=:id')->execute([':id'=>$id]);
            $ins=$pdo->prepare('INSERT INTO scene_actions(scene_id,ordem,device_id,comando,payload,prioridade,required_capability,risk_level,ttl_seconds,enabled) VALUES(:s,:o,:d,:c,:p,:pr,:cap,:r,:ttl,:en)');
            $order=10; foreach($actions as $a){ if(!is_array($a))continue; $dev=trim((string)($a['device_id']??''));$cmd=trim((string)($a['command']??$a['comando']??''));if($dev===''||$cmd==='')continue;$pr=strtolower((string)($a['priority']??'normal'));if(!in_array($pr,['low','normal','high','critical'],true))$pr='normal';$ins->execute([':s'=>$id,':o'=>(int)($a['order']??$order),':d'=>$dev,':c'=>substr($cmd,0,120),':p'=>json_encode(is_array($a['payload']??null)?$a['payload']:[],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),':pr'=>$pr,':cap'=>trim((string)($a['required_capability']??''))?:null,':r'=>max(0,min(4,(int)($a['risk_level']??1))),':ttl'=>max(10,min(86400,(int)($a['ttl_seconds']??300))),':en'=>(int)($a['enabled']??1)]);$order+=10; }
            $pdo->commit(); $message='Cena salva.';
        } elseif ($action==='scene_toggle') {
            $id=(int)$_POST['id']; $pdo->prepare('UPDATE scenes SET ativo=IF(ativo=1,0,1) WHERE id=:id')->execute([':id'=>$id]); $message='Cena atualizada.';
        } elseif ($action==='rule_save') {
            $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');if($name==='')throw new RuntimeException('Informe o nome da regra.');$slug=slugify_auto($_POST['slug']??$name);$type=$_POST['trigger_type']??'event';if(!in_array($type,['event','state','schedule'],true))$type='event';
            $trigger=json_arr($_POST['trigger_json']??'{}');$conditions=json_arr($_POST['conditions_json']??'[]');$actions=json_arr($_POST['actions_json']??'[]');$enabled=isset($_POST['enabled'])?1:0;$cool=max(0,min(86400,(int)($_POST['cooldown_seconds']??0)));$desc=trim($_POST['description']??'');
            if($id>0){$pdo->prepare('UPDATE automation_rules SET slug=:s,nome=:n,descricao=:d,enabled=:e,trigger_type=:t,trigger_config=:tc,conditions_json=:c,cooldown_seconds=:cd WHERE id=:id')->execute([':s'=>$slug,':n'=>$name,':d'=>$desc,':e'=>$enabled,':t'=>$type,':tc'=>json_encode($trigger,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),':c'=>json_encode($conditions,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),':cd'=>$cool,':id'=>$id]);}
            else{$pdo->prepare('INSERT INTO automation_rules(slug,nome,descricao,enabled,trigger_type,trigger_config,conditions_json,cooldown_seconds) VALUES(:s,:n,:d,:e,:t,:tc,:c,:cd)')->execute([':s'=>$slug,':n'=>$name,':d'=>$desc,':e'=>$enabled,':t'=>$type,':tc'=>json_encode($trigger,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),':c'=>json_encode($conditions,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),':cd'=>$cool]);$id=(int)$pdo->lastInsertId();}
            $pdo->beginTransaction();$pdo->prepare('DELETE FROM automation_rule_actions WHERE rule_id=:id')->execute([':id'=>$id]);$ins=$pdo->prepare('INSERT INTO automation_rule_actions(rule_id,ordem,device_id,comando,payload,prioridade,required_capability,risk_level,ttl_seconds,enabled) VALUES(:r,:o,:d,:c,:p,:pr,:cap,:risk,:ttl,:en)');$order=10;foreach($actions as $a){if(!is_array($a))continue;$dev=trim((string)($a['device_id']??''));$cmd=trim((string)($a['command']??$a['comando']??''));if($dev===''||$cmd==='')continue;$pr=strtolower((string)($a['priority']??'normal'));if(!in_array($pr,['low','normal','high','critical'],true))$pr='normal';$ins->execute([':r'=>$id,':o'=>(int)($a['order']??$order),':d'=>$dev,':c'=>substr($cmd,0,120),':p'=>json_encode(is_array($a['payload']??null)?$a['payload']:[],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),':pr'=>$pr,':cap'=>trim((string)($a['required_capability']??''))?:null,':risk'=>max(0,min(4,(int)($a['risk_level']??1))),':ttl'=>max(10,min(86400,(int)($a['ttl_seconds']??300))),':en'=>(int)($a['enabled']??1)]);$order+=10;}$pdo->commit();$message='Regra salva.';
        } elseif ($action==='rule_toggle') {
            $id=(int)$_POST['id'];$pdo->prepare('UPDATE automation_rules SET enabled=IF(enabled=1,0,1) WHERE id=:id')->execute([':id'=>$id]);$message='Regra atualizada.';
        }
    } catch(Throwable $e){ if($pdo->inTransaction())$pdo->rollBack(); $error=$e->getMessage(); }
}

$scenes=$pdo->query("SELECT s.*,COUNT(a.id) actions_total FROM scenes s LEFT JOIN scene_actions a ON a.scene_id=s.id AND a.enabled=1 GROUP BY s.id ORDER BY s.nome")->fetchAll(PDO::FETCH_ASSOC);
$rules=$pdo->query("SELECT r.*,COUNT(a.id) actions_total FROM automation_rules r LEFT JOIN automation_rule_actions a ON a.rule_id=r.id AND a.enabled=1 GROUP BY r.id ORDER BY r.nome")->fetchAll(PDO::FETCH_ASSOC);
?>
