body{background:#fff7e8;color:#211b22;font-family:Arial,sans-serif;margin:0}.wrap{max-width:1200px;margin:auto;padding:18px}.head{display:flex;gap:12px}.elbow{background:#f59c73;border-radius:28px 0 0 28px;padding:22px;min-width:150px;font-weight:900}.title{background:#d8b4ea;flex:1;padding:18px 24px;border-radius:0 24px 24px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:14px;margin-top:16px}.card{background:#fff;border:3px solid #d8b4ea;border-radius:20px;padding:16px}.orange{border-color:#f59c73}.blue{border-color:#8eb9ee}.green{border-color:#8ccf9c}input,textarea,select,button{font:inherit;padding:9px;border-radius:9px;border:1px solid #777;box-sizing:border-box}input,textarea,select{width:100%}textarea{font-family:monospace}button{background:#f59c73;font-weight:800;cursor:pointer}.row{display:flex;gap:8px;align-items:center}.row>*{flex:1}.pill{display:inline-block;padding:5px 10px;border-radius:999px;font-weight:800}.on{background:#9bd6a4}.off{background:#ef9b92}.msg{padding:10px;border-radius:10px;background:#dff3df;margin-top:12px}.err{background:#ffd9d3}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}.top a{display:inline-block;padding:10px 14px;background:#8eb9ee;border-radius:12px;color:#211b22;text-decoration:none;font-weight:800;margin-right:6px}</style></head><body><div class="wrap">
