<?php if($message):?><div class="msg"><?=h($message)?></div><?php endif;?><?php if($error):?><div class="msg err"><?=h($error)?></div><?php endif;?>
<div class="grid"><div class="card orange"><h2>Nova cena</h2><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="scene_save"><label>Nome<input name="name" required></label><label>Slug<input name="slug"></label><label>Descrição<textarea name="description" rows="2"></textarea></label><div class="row"><label>Risco<select name="risk_level"><?php for($i=0;$i<=4;$i++):?><option><?=$i?></option><?php endfor;?></select></label><label><input type="checkbox" name="active" checked> Ativa</label><label><input type="checkbox" name="stop_on_error"> Parar no erro</label></div><label>Ações JSON<textarea name="actions_json" rows="10">[
  {"device_id":"luz_sala","command":"power_on","payload":{},"risk_level":1}
]</textarea></label><button>Salvar cena</button></form></div>
<div class="card blue"><h2>Nova regra</h2><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="rule_save"><label>Nome<input name="name" required></label><label>Slug<input name="slug"></label><label>Tipo<select name="trigger_type"><option value="event">Evento</option><option value="state">Estado</option><option value="schedule">Horário</option></select></label><label>Trigger JSON<textarea name="trigger_json" rows="4">{"event_type":"sensor.presence","device_id":"sensor_corredor"}</textarea></label><label>Condições JSON<textarea name="conditions_json" rows="4">[{"field":"data.presence","op":"eq","value":true}]</textarea></label><label>Ações JSON<textarea name="actions_json" rows="5">[{"device_id":"luz_corredor","command":"power_on","risk_level":1}]</textarea></label><div class="row"><label>Cooldown<input type="number" name="cooldown_seconds" value="30" min="0"></label><label><input type="checkbox" name="enabled" checked> Ativa</label></div><button>Salvar regra</button></form></div></div>
<div class="card green" style="margin-top:16px"><h2>Cenas cadastradas</h2><table><tr><th>Nome</th><th>Risco</th><th>Ações</th><th>Estado</th><th></th></tr><?php foreach($scenes as $s):?><tr><td><?=h($s['nome'])?><br><small><?=h($s['slug'])?></small></td><td><?=h($s['risk_level'])?></td><td><?=h($s['actions_total'])?></td><td><span class="pill <?=$s['ativo']?'on':'off'?>"><?=$s['ativo']?'ATIVA':'DESATIVADA'?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="scene_toggle"><input type="hidden" name="id" value="<?=h($s['id'])?>"><button>Alternar</button></form></td></tr><?php endforeach;?></table></div>
<div class="card blue" style="margin-top:16px"><h2>Regras cadastradas</h2><table><tr><th>Nome</th><th>Tipo</th><th>Ações</th><th>Último disparo</th><th>Estado</th><th></th></tr><?php foreach($rules as $r):?><tr><td><?=h($r['nome'])?><br><small><?=h($r['slug'])?></small></td><td><?=h($r['trigger_type'])?></td><td><?=h($r['actions_total'])?></td><td><?=h($r['last_triggered_at']?:'—')?></td><td><span class="pill <?=$r['enabled']?'on':'off'?>"><?=$r['enabled']?'ATIVA':'DESATIVADA'?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="rule_toggle"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button>Alternar</button></form></td></tr><?php endforeach;?></table></div>
</div></body></html>
